SELECT COUNT(*) AS unique_visitors
FROM agg_daily_users
WHERE summary_date = current_date - 1;

WITH daily_uv AS (
    SELECT
        summary_date,
        count(*) AS unique_visitors
    FROM agg_daily_users
    WHERE summary_date >= current_date - 14
      AND summary_date < current_date
    GROUP BY summary_date
)
SELECT
    avg(unique_visitors) FILTER (
        WHERE summary_date >= current_date - 7
    ) AS recent_7d_daily_avg_unique_visitors,
    avg(unique_visitors) FILTER (
        WHERE summary_date < current_date - 7
    ) AS previous_7d_daily_avg_unique_visitors,
    avg(unique_visitors) FILTER (
        WHERE summary_date >= current_date - 7
    ) - avg(unique_visitors) FILTER (
        WHERE summary_date < current_date - 7
    ) AS difference,
    (
        avg(unique_visitors) FILTER (
            WHERE summary_date >= current_date - 7
        ) - avg(unique_visitors) FILTER (
            WHERE summary_date < current_date - 7
        )
    ) * 100.0 / NULLIF(
        avg(unique_visitors) FILTER (
            WHERE summary_date < current_date - 7
        ),
        0
    ) AS change_percent
FROM daily_uv;
